using Microsoft.AspNetCore.Mvc; using Azure.Data.Tables; using Azure.Identity; namespace App_API.Controllers { [AllowAnonymous][HttpGet("co-drivers")] public async Task<IActionResult> Get() { int n=0; var u=System.Environment.GetEnvironmentVariable("azureStorageUri"); var c=new DefaultAzureCredential(); await foreach(var _ in new TableServiceClient(new System.Uri(u),c).GetTableClient(TableNames.tblPersonEventIndex).QueryAsync<Azure.Data.Tables.TableEntity>(filter:"Role eq 'CoDriver'")) n++; return Ok(new{count=n}); } }